using System;using System.IO;using System.Collections.Generic;using ScoreModern.RecoveredFragments;
class BufferedPointGateProof {
 class Memory:IHorizontalRasterMemory {public Dictionary<int,byte> Bytes=new Dictionary<int,byte>();public List<string> Events=new List<string>();public void Seed(ushort s,ushort o,ushort v){Bytes[(s<<4)+o]=(byte)v;Bytes[(s<<4)+(ushort)(o+1)]=(byte)(v>>8);}public ushort ReadWord(ushort s,ushort o){byte a,b;Bytes.TryGetValue((s<<4)+o,out a);Bytes.TryGetValue((s<<4)+(ushort)(o+1),out b);ushort v=(ushort)(a|b<<8);Events.Add("R:"+s+":"+o+":"+v);return v;}public void WriteWord(ushort s,ushort o,ushort v){Events.Add("W:"+s+":"+o+":"+v);Seed(s,o,v);}public void OrByte(ushort s,ushort o,byte b){throw new Exception("Video");}public Memory Copy(){Memory m=new Memory();foreach(var v in Bytes)m.Bytes[v.Key]=v.Value;return m;}}
 static string Show(SignedDivide16State s){return s.AX+":"+s.BX+":"+s.CX+":"+s.DX+":"+s.SI+":"+s.DI+":"+s.BP+":"+s.CS+":"+s.IP+":"+s.DS+":"+s.ES+":"+s.SS+":"+s.SP+":"+s.EFlags;}
 static BufferedPointCallerResult Interpret(byte[] code,Memory m,SignedDivide16State s){int pc=0;bool less=false;Func<byte> next=()=>code[pc++];Func<ushort> word=()=>{byte b=next();return (ushort)(b|next()<<8);};while(pc<18){switch(next()){
 case 0x55:s.SP=(ushort)(s.SP-2);m.WriteWord(s.SS,s.SP,s.BP);break;case 0x8b:if(next()!=0xec)throw new Exception("MOV");s.BP=s.SP;break;case 0x56:s.SP=(ushort)(s.SP-2);m.WriteWord(s.SS,s.SP,s.SI);break;
 case 0x8e:if(next()!=6)throw new Exception("MOV ES");s.ES=m.ReadWord(s.DS,word());break;case 0xa1:s.AX=m.ReadWord(s.DS,word());break;
 case 0x26:if(next()!=0x39||next()!=6)throw new Exception("CMP");ushort value=m.ReadWord(s.ES,word());s.EFlags=IndependentFlagArithmetic.Apply(s.EFlags,value,s.AX,16,false);less=(short)value<(short)s.AX;break;
 case 0x7c:sbyte d=(sbyte)next();if(less)pc+=d;break;default:throw new Exception("Opcode");}}
 s.IP=(ushort)(0x752+pc);return new BufferedPointCallerResult{State=s,Outcome=less?BufferedPointOutcome.NormalPathReady:BufferedPointOutcome.CapacityHandlerRequired,RequestedCalleeOffset=less?(ushort)0:(ushort)0x84f};}
 static int Main(string[] a){try{byte[] raw=File.ReadAllBytes(a[0]),code=new byte[18];Array.Copy(raw,0xc250+0x752,code,0,18);int count=0;for(int n=0;n<65536;n++)for(int k=0;k<4;k++){ushort ds=0x2000,ss=(ushort)((k&1)==0?ds:0x3000),first=(ushort)((k&2)==0?ds:0x4000),limit=new ushort[]{0,31000,0x7fff,0x8000}[k];var s=new SignedDivide16State{AX=(ushort)(n*3),BX=(ushort)(n*5),CX=(ushort)(n*7),DX=(ushort)(n*11),SI=(ushort)(n*13),DI=(ushort)(n*17),BP=(ushort)(n*19),CS=0x1449,IP=0x752,DS=ds,SS=ss,SP=(ushort)n,ES=0x5678,EFlags=unchecked((uint)(n*65537+0xa55a))};Memory seed=new Memory();seed.Seed(ds,0x69da,first);seed.Seed(ds,0x80de,limit);seed.Seed(first,0,(ushort)n);Memory x=seed.Copy(),y=seed.Copy();var p=BufferedPointCaller.Enter(x,s);var q=Interpret(code,y,s);if(Show(p.State)!=Show(q.State)||p.Outcome!=q.Outcome||p.RequestedCalleeOffset!=q.RequestedCalleeOffset||x.Events.Count!=y.Events.Count||x.Bytes.Count!=y.Bytes.Count)throw new Exception("Gate state");for(int i=0;i<x.Events.Count;i++)if(x.Events[i]!=y.Events[i])throw new Exception("Gate order");foreach(var v in x.Bytes)if(y.Bytes[v.Key]!=v.Value)throw new Exception("Gate memory");count++;}
 Console.WriteLine("PASS "+count+" original-instruction capacity-entry comparisons: all count/SP words, four limits, alias layouts, ordered prologue effects and full flags. Capacity callee execution remains unverified and unported.");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
